</script>

    <div class="container mx-auto px-3 py-4 max-w-3xl">
        <!-- 整合后的状态栏区块 -->
        <div class="status-block mb-4 bg-dark rounded-2xl shadow-lg overflow-hidden border border-gray-700/30 theme-transition">
            <!-- 顶部信息和主题切换栏 -->
